# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением (разбор по случаям параметра, числовая сетка по $a$)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_27_2_67_1", r"$u=\sqrt{\frac x4-3}\ge0$, $\sqrt{u^{2}+5}=c+u\Rightarrow u=\frac{5-c^{2}}{2c}$; условие $u\ge0$ и $c+u>0$ даёт $0<c\le\sqrt5$ (при $c>\sqrt5$ $u<0$: например $c=3$ решений нет); в ключе не было ограничения $c\le\sqrt5$",
  k=r"$x=4 \cdot \left( \dfrac{(c^{2}-5)^{2}}{4c^{2}}+3 \right)$ при $0<c\le\sqrt{5}$; нет решений при $c \leq 0$ и при $c>\sqrt{5}$")
E("G11_TB_27_2_67_3", r"$c\sqrt{x-1}=\pi\frac{6k+(-1)^{k}-1}{6}=q_k$; $\sqrt{x-1}\ge0$, поэтому $q_k/c\ge0$: при $c>0$ подходят $k\ge0$, при $c<0$ — $k\le0$ (пример: $c=1$, $k=-1$: $q=-\frac{4\pi}{3}$, $\sin(-\frac{4\pi}3+\frac\pi6)=-1$); в ключе не было ограничения на знак $k$",
  k=r"$x=1+\dfrac{\pi^{2}(6k+(-1)^{k}-1)^{2}}{36c^{2}}$ при $c\neq 0$, где целое $k$ такое, что $kc\ge 0$ ($k\ge0$ при $c>0$ и $k\le0$ при $c<0$); при $c=0$ $x\geq 1$")
E("G11_TB_27_2_71", r"$f(x)=|2x+6|+|2x-8|$: $-4x+2$ при $x<-3$, $14$ на $[-3;4]$, $4x-2$ при $x>4$; прямая $y=ax+12$: одна общая точка при $a\le-4$ (только на средней части), $a=-\frac23$, $a=\frac12$, $a\ge4$ (сетка по $a$ подтверждает); в ключе не было $a\le-4$",
  k=r"$a \le -4$, $a = \dfrac{-2}{3}$, $a = 0{,}5$, $a \geq 4$")
